// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Ensure caller is not zero address to avoid revert in transferOwnership
        vm.assume(caller != address(0));
        // Call XBornID() to initialize the contract (sets owner's balance)
        c.XBornID();
        // Call finishDistribution via caller (must be owner to pass onlyOwner)
        // The reference always returns true; the bug returns false.
        bool result = c.finishDistribution();
        // The general rule: finishDistribution must return true
        assertTrue(result);
    }
}

